// ⚠️2026-09-14改修: 「済んだ」の判定をシフト表の行→名簿の役割へ（staffRegDone_ が唯一の判定）。
//   待ちが1件も無い毎分は名簿を読まない（従来どおりプロパティを見るだけ）。
//   ⚠️例外はここで止める＝毎分ジョブの後続（定時通知）を巻き込まない。
function checkPendingStaffRegistrations_() {
  const props = PropertiesService.getScriptProperties().getProperties();
  const keys = Object.keys(props).filter(k => k.startsWith('PENDING_REG_'));
  if (!keys.length) return;
  let rows = null;
  try { rows = staffRosterValues_(); } catch (e) { console.error('checkPendingStaffRegistrations_', e); return; }
  keys.forEach(k => {
    try {
      const userId = k.slice('PENDING_REG_'.length);
      const name = props[k];
      if (!staffRegDone_(userId, name, rows)) return;
      staffRegNotifyDone_(userId, name);
    } catch (e) { console.error('checkPendingStaffRegistrations_', k, e); }
  });
}

/* ============================================================
   🆕 新規スタッフ登録＝コンソールの画面だけで終わらせる（2026-09-14 ボス指示）
   ------------------------------------------------------------
   ボス原文「新規スタッフが入ったときに、スタッフの時給等が入力されていないとエラーになるような仕組みに」
           「LINEで登録させたあとに、スプシでなにか作業が必要になっているけど、それを省略したい」
   ⭐必須＝基本時給・基本バック・入店日（ボス確定）。判定は staffRegMissing_ の**1箇所だけ**。
     コンソールの「登録を完了」・役割の変更（setStaffRole_）・カードの⚠️表示が全部これを呼ぶ。
   ⭐対象の役割＝日報で時給から報酬が出る役割＝nippoRoleKubun_ が区分を返す役割
     （キャスト/体験/派遣/黒服社員/黒服バイト）。ドライバー・管理者・管理アカウント・テストスタッフは対象外。
     ⚠️役割→区分の規則を2つ持たない＝日報の nippoRoleKubun_ をそのまま使う。
   ⭐関所は「役割が空の人に役割を付ける」瞬間だけ（＝#登録で来た新人）。既に役割がある人は止めない
     （在籍者の基本バック・入店日はほぼ全員空＝ここを止めると誰の役割も変えられなくなる）。
   ⭐完了したら、その場で ①シフト表に行を作る（addShiftStaff_ を再利用・二重実装しない）
     ②PENDING_REG_ を消して本人に完了LINE（staffRegNotifyDone_＝毎分ジョブと同じ1本）。
============================================================ */
var STAFF_REQUIRED_TERMS_ = ['基本時給', '基本バック', '入店日'];

// この役割は必須3項目が要るか。⚠️nippo.gs が無い環境では要らない扱い（止める方に倒さない）
function staffTermsRequired_(role) {
  return (typeof nippoRoleKubun_ === 'function') && nippoRoleKubun_(role) !== '';
}

// 時給の読み方は日報と同じ（全角・カンマ・円記号を吸収）。⚠️名簿の基本時給は文字列で入っている
function staffWageYen_(v) {
  if (typeof nippoYen_ === 'function') return nippoYen_(v);
  const n = parseFloat(String(v == null ? '' : v).replace(/[，,¥￥円\s　]/g, ''));
  return isNaN(n) ? 0 : Math.round(n);
}

/* ⭐必須項目の判定の正本。空いている項目名の配列を返す（空配列＝揃っている）。
   基本時給＝1円以上の数として読めること／入店日＝日付（Date か 2026-09-14・2026/9/14 の形）／基本バック＝空でないこと。 */
function staffRegMissing_(role, terms) {
  if (!staffTermsRequired_(role)) return [];
  const t = terms || {};
  return STAFF_REQUIRED_TERMS_.filter(function (h) {
    const v = t[h];
    if (h === '基本時給') return !(staffWageYen_(v) > 0);
    if (h === '入店日') {
      if (v instanceof Date) return isNaN(v.getTime());
      return !/^\d{4}[-\/年]\d{1,2}[-\/月]\d{1,2}/.test(String(v == null ? '' : v).trim());
    }
    return String(v == null ? '' : v).trim() === '';
  });
}

// 名簿の1行から必須3項目を取り出す（列は見出しで引く＝位置読みしない）
function staffTermsOfRow_(row, cols) {
  const t = {};
  STAFF_REQUIRED_TERMS_.forEach(function (h) {
    const c = cols ? cols[h] : -1;
    t[h] = (c != null && c >= 0) ? row[c] : '';
  });
  return t;
}

function staffRosterValues_() {
  const sh = getOrOpenSS_().getSheetByName(STAFF_TAB);
  return sh ? sh.getDataRange().getValues() : [];
}

/* ⭐「登録が済んだか」の判定の正本＝名簿に役割が入っているか（userId か 名前で当たる行）。
   ⚠️名前でも当てる＝LINEを変えて #登録 し直した在籍者（別の行が増える）を「待ち」にしない（旧判定と同じ振る舞い）。 */
function staffRegDone_(userId, name, rows) {
  const vals = rows || staffRosterValues_();
  const uid = String(userId == null ? '' : userId).trim();
  const key = shiftNameKey_(name);
  for (let i = 1; i < vals.length; i++) {
    const hit = (uid && String(vals[i][0]).trim() === uid) || (key && shiftNameKey_(vals[i][1]) === key);
    if (hit && String(vals[i][2] == null ? '' : vals[i][2]).trim()) return true;
  }
  return false;
}

/* 登録完了のLINE（本人へ）。⭐文面と送り口はここ1本＝毎分ジョブとコンソールの完了が同じ物を通る。
   ⚠️待ち（PENDING_REG_）が無ければ送らない＝#登録していない人・もう送った人に二度送らない。 */
function staffRegNotifyDone_(userId, name) {
  const uid = String(userId == null ? '' : userId).trim();
  if (!uid) return false;
  const p = PropertiesService.getScriptProperties();
  const k = 'PENDING_REG_' + uid;
  /* 🔒「待ちを読んで消す」を1つの錠の中で行う（2026-09-14 qa穴4）＝毎分ジョブとコンソールの完了が重なっても1通。
     ⛔ScriptLock は使わない＝scheduledJobs が冒頭で取って最後まで返さない（奪い合うと毎分ジョブが丸ごと飛ぶ＝perfmonで踏んだ罠）。
       UserLock を使う（トリガーもWebアプリ(USER_DEPLOYING)も同じ所有者で動く＝同じ錠）。
       ⚠️UserLock は perfRec_（遅さの記録）も使う＝**業務の錠ではないが専用でもない**。
         重なるのは登録完了の数ミリ秒だけ。perfRec_ は tryLock(0) なので**その瞬間の遅さの記録が1件落ちる**だけ／
         こちらは最大5秒待つので完了LINEは落ちない。
     ⚠️錠の中は読む・消すだけ＝LINE送信（UrlFetch）は錠の外。長く握ると perfRec_ の記録を落とす。
     ⚠️錠が取れなければ送らず待ちを残す＝次の毎分ジョブが送る（取れないことを理由に二度送らない）。 */
  let pendingName = null;
  const lock = LockService.getUserLock();
  if (!lock.tryLock(5000)) return false;
  try {
    pendingName = p.getProperty(k);
    if (pendingName) p.deleteProperty(k);
  } finally { lock.releaseLock(); }
  if (!pendingName) return false;
  push_(uid, (name || pendingName) + ' さん、登録が完了しました🎉\nマイページからシフト提出などがご利用いただけます。');
  return true;
}

/* 役割を付けて登録が済んだ直後の後始末。⚠️ここで失敗しても役割は入っている＝登録そのものは戻さない。
   シフト表の行は、無くてもシフト提出時に writeShiftCell_ が名簿から作る＝あれば便利な物（黒服の手入力を省く）。 */
function staffRegFinish_(name, userId, role) {
  const out = { shiftRow: 'skip', notified: false };
  try {
    if (staffTermsRequired_(role)) {
      if (isStaffInShiftSheet_(name)) out.shiftRow = 'exists';
      else {
        const r = addShiftStaff_(name, role, '', '', userId);   // ⭐既存の「シフト表に人を足す」をそのまま使う
        out.shiftRow = (r && r.ok) ? 'created' : ('error: ' + ((r && r.error) || '不明'));
        try { if (typeof tsdCacheClear_ === 'function') tsdCacheClear_(); } catch (e) {}
        try { if (typeof pcacheDrop_ === 'function') pcacheDrop_('shift'); } catch (e) {}   // ⚡ポータルのシフト表キャッシュ
      }
    }
  } catch (e) { out.shiftRow = 'error: ' + e; }
  try { out.notified = staffRegNotifyDone_(userId, name); } catch (e) { console.error('staffRegFinish_', e); }
  return out;
}

