/* 🆕 管理コンソール「登録を完了」＝役割と必須3項目を1回で入れる（2026-09-14 ボス指示）。
   ⭐判定は staffRegMissing_ だけ。足りなければ**何も書かずに**足りない項目名を返す（画面が赤くする）。
   ⭐揃っていれば ①必須3項目を名簿へ ②setStaffRole_（関所の正本・シフト表の行・完了LINE）。
   ⚠️既に役割がある人には使わせない＝在籍者の役割の変更はカードの「属性」から（関所を掛けない既存の道）。
   👥同じ名前の行がある時（2026-09-14 ボス確定「A＝1行にまとめる」）:
     ・面談表の体験登録（LINE IDなし）の本人が #登録 すると、同じ名前で役割が空の行がもう1つ増える。
       2行のままだと、名前で名簿を引く読み手（日報の時給 nippoStaffMap_・getStaffRoleByName_ ほか）は1行目を返す
       ＝時給0・役割「体験」のまま＝日報の関所が毎晩鳴る。
     ・opts.merge 無し → 何も書かずに needConfirm を返す（**同じ人かは人が決める**＝自動で結び付けない）。
     ・opts.merge==='same' → staffMergeReg_ で既存の行（LINE IDなし）に LINE ID・役割・必須3項目を書き、#登録で増えた行を消す。
     ・それ以外（別人）→ 止める。**同じ名前の別人を名簿に並べない**（名前で引く読み手が取り違える）。
     ・画面から行番号やIDは受け取らない＝どの2行かは**サーバが名簿から決め直す**（staffRegSameName_）。 */
function adminCompleteStaffReg(userId, targetName, role, terms, opts) {
  if (!isAdmin_(getStaffName(userId))) return { ok: false, error: '権限がありません' };
  targetName = String(targetName || '').trim();
  role = String(role || '').trim();
  if (!role) return { ok: false, missing: ['役割'], error: '役割を選んでください' };
  if (ADMIN_ROLES_.indexOf(role) < 0) return { ok: false, error: '不明な属性: ' + role };
  var sh = getOrOpenSS_().getSheetByName(STAFF_TAB);
  if (!sh) return { ok: false, error: 'スタッフマスタが見つかりません' };
  var rows = sh.getDataRange().getValues();
  var w = staffRegTermsInput_(terms);
  var sn = staffRegSameName_(sh, rows, targetName);
  if (sn.error) return { ok: false, error: sn.error };
  if (sn.q >= 0 || sn.blocked) {
    /* 👥同じ名前の行がある */
    if (sn.blocked) return { ok: false, sameName: true, blockedWhy: sn.blockedWhy, error: staffSameNameMsg_(sn.otherName, sn.blockedWhy) };
    var qName = String(rows[sn.q][1]).trim(), qRole = String(rows[sn.q][2] == null ? '' : rows[sn.q][2]).trim();
    var mode = String((opts && opts.merge) || '');
    if (!mode) {
      return { ok: false, needConfirm: true, name: targetName, sameAs: { name: qName, role: qRole },
               error: '同じ名前の行があります',
               confirmText: '「' + targetName + '」さんは、' + (qRole ? qRole + ' で' : '') + '登録済みの「' + qName + '」さんと同じ人ですか？\n\n'
                 + 'OK＝同じ人（1行にまとめます）\nキャンセル＝別人（登録を止めます）\n\n⚠️まとめている間は、名簿シートを手で行削除・並べ替えしないでください。' };
    }
    if (mode !== 'same') return { ok: false, sameName: true, error: staffSameNameMsg_(qName) };
    return staffMergeReg_(sh, targetName, role, w, String(rows[sn.p][0] == null ? '' : rows[sn.p][0]).trim());
  }
  /* 同じ名前の行が無い＝この1行だけ（今の本番はすべてこの形） */
  var merged = staffTermsOfRow_(rows[sn.p], getStaffTermCols_(sh, false));
  Object.keys(w).forEach(function (h) { merged[h] = w[h]; });
  var miss = staffRegMissing_(role, merged);
  if (miss.length) {
    return { ok: false, missing: miss, name: targetName,
             error: miss.join('・') + ' が未入力です（' + role + 'は 基本時給・基本バック・入店日 が必須です）' };
  }
  if (Object.keys(w).length) {
    var r1 = saveStaffTerms_(targetName, w);
    if (!r1 || !r1.ok) return r1 || { ok: false, error: '個別条件の保存に失敗しました' };
  }
  return setStaffRole_(targetName, role);
}

/* 画面から来た必須3項目を整える（来た項目だけ）。「５,０００円」→「5000」 */
function staffRegTermsInput_(terms) {
  var w = {};
  STAFF_REQUIRED_TERMS_.forEach(function (h) {
    if (terms && Object.prototype.hasOwnProperty.call(terms, h)) {
      var v = String(terms[h] == null ? '' : terms[h]).trim();
      if (h === '基本時給' && staffWageYen_(v) > 0) v = String(staffWageYen_(v));
      w[h] = v;
    }
  });
  return w;
}

/* 👥「登録待ちの行（p）」と「同じ名前の既存の行（q）」を**名簿から決める**（画面の申告は使わない）。
   p＝名前が完全一致・役割が空の行（LINE IDのある行を優先・1つに決まらなければ止める）。
   同じ名前＝shiftNameKey_（空白ゆらぎ込み・既存の正規化）。
   q＝まとめてよい相手＝**LINE IDが空・在籍（退職でない）**の行が**ちょうど1つ**。
   blocked＝LINE IDのある同名の行・退職済みの同名の行・まとめ先の候補が2つ以上・p にLINE IDが無い（どれとも結び付けない）。
   戻り値 { p, q(-1=同名なし), blocked, blockedWhy, otherName（案内に出す同名の人の表記）, error } */
function staffRegSameName_(sh, rows, targetName) {
  var name = String(targetName || '').trim();
  var rc = -1;
  try { var c = getStaffRetireCols_(sh, false)['退職']; if (c != null && c >= 0) rc = c; } catch (e) {}
  var A = function (i) { return String(rows[i][0] == null ? '' : rows[i][0]).trim(); };
  var C = function (i) { return String(rows[i][2] == null ? '' : rows[i][2]).trim(); };
  var retired = function (i) { return rc >= 0 && String(rows[i][rc] == null ? '' : rows[i][rc]).trim() === '退職'; };
  var exact = [], unset = [];
  for (var i = 1; i < rows.length; i++) {
    if (!name || String(rows[i][1] == null ? '' : rows[i][1]).trim() !== name) continue;
    exact.push(i);
    if (!C(i)) unset.push(i);
  }
  if (!exact.length) return { error: name + ' が見つかりません' };
  if (!unset.length) return { error: name + ' は登録済みです（役割: ' + C(exact[0]) + '）。役割の変更はカードの「属性」から' };
  var withId = unset.filter(function (k) { return !!A(k); });
  var p = (withId.length === 1) ? withId[0] : (unset.length === 1 ? unset[0] : -1);
  if (p < 0) return { error: name + ' という名前で役割が空の行が複数あります（名簿を確認してください）' };
  var key = shiftNameKey_(name);
  var others = [];
  for (var j = 1; j < rows.length; j++) {
    if (j === p || !String(rows[j][1] == null ? '' : rows[j][1]).trim()) continue;
    if (shiftNameKey_(rows[j][1]) === key) others.push(j);
  }
  if (!others.length) return { p: p, q: -1, blocked: false };
  var why = [];
  if (!A(p)) why.push('登録待ちの行にLINE IDがありません');
  others.forEach(function (k) {
    if (retired(k)) why.push('退職済みの「' + String(rows[k][1]).trim() + '」があります');
    else if (A(k)) why.push('LINE登録済みの「' + String(rows[k][1]).trim() + '」があります');
  });
  var cand = others.filter(function (k) { return !A(k) && !retired(k); });
  if (!why.length && cand.length !== 1) why.push('LINE未登録の同じ名前の行が' + cand.length + 'つあります');
  if (why.length) return { p: p, q: -1, blocked: true, blockedWhy: why.join('・'), otherName: String(rows[others[0]][1]).trim() };
  return { p: p, q: cand[0], blocked: false };
}

/* 👥 同じ人として1行にまとめる（ボス確定A）。**画面の申告を信じず、行番号も信じない**。
   2026-09-15 PM決定（qa4回目）＝**行を消さない・書き戻さない・嘘をつかない**。
     行を消す（deleteRow）と行の位置がずれ、人の手作業（行削除・挿入）と重なった瞬間に別人を消す／書き戻しで消した人が復活する。
     ⇒ #登録で増えた行は**中身を空にするだけ**（clearContent・見出しの列幅ぶん・書式は触らない）＝こちらからは位置を一切ずらさない。
   順番:
     ① 1回目の読み＝どの2行か・中身（名前・LINE ID）を決める（まだ書かない）
     ② 参照確認（別ブックを開く＝秒単位）を**書くための読み直しより前に**済ませる
     ③ UserLock（#登録削除の deleteStaff と同じ錠）。取れなければ何も書かずに「混み合っています」
     ④ 錠の中で読み直し、2行を**中身で**決め直す（①と違えば何も書かずに止める）
     ⑤ 既存の行へ 必須3項目 → 役割 → LINE ID（最後）。**各書き込みの直前にその行番号の1行だけを読み**、名前と「LINE ID が空」を確かめてから書く
     ⑥ 書いた行を1行だけ読み、**書いた値そのもの**か確かめる
     ⑦ #登録の行を1行だけ読み、名前・LINE ID・役割（空）が「#登録の行そのもの」の時だけ中身を空にし、空になったことを1行読んで確かめる
   ⚠️戻すのは**自分が書いた行**だけ（その行番号の行が、名前＝既存の行の名前・LINE ID＝自分が書いた値か空）。
   ⚠️戻せなかった項目・確かめられなかった行があれば「元に戻しました」とは言わない＝**行番号・その行の名前・項目**を挙げて確認を頼む。
   ⚠️残る穴＝「1行を読んでから書く／空にする」までの一瞬に人が名簿シートを手で行削除・挿入すると別の行に当たりうる（APIでは防げない）。
     その時は書いた後の確かめで気づき、行番号と項目を挙げて知らせる。運用＝コンソールの確認文に「まとめている間は名簿シートを手で行削除・並べ替えしない」。 */
function staffMergeReg_(sh, targetName, role, w, expectUid) {
  var cell = function (vals, i, c) { return (i >= 1 && i < vals.length) ? String(vals[i][c] == null ? '' : vals[i][c]).trim() : null; };
  /* ① */
  var rows = sh.getDataRange().getValues();
  var sn = staffRegSameName_(sh, rows, targetName);
  if (sn.error) return { ok: false, error: sn.error };
  if (sn.blocked || sn.q < 0) return { ok: false, sameName: true, error: staffSameNameMsg_(sn.otherName, sn.blockedWhy) };
  var pUid = cell(rows, sn.p, 0), pName = cell(rows, sn.p, 1), qName = cell(rows, sn.q, 1);
  if (!pUid || cell(rows, sn.p, 2) || pName !== targetName) return { ok: false, error: 'まとめる行を確かめられませんでした（登録待ちの行が変わっています）' };
  if (cell(rows, sn.q, 0) || shiftNameKey_(qName) !== shiftNameKey_(pName)) return { ok: false, error: 'まとめる行を確かめられませんでした（既存の行が変わっています）' };
  if (expectUid != null && String(expectUid) !== pUid) return { ok: false, error: 'まとめる行を確かめられませんでした（名簿が途中で変わりました）' };
  var cols = getStaffTermCols_(sh, false);
  var merged = staffTermsOfRow_(rows[sn.q], cols);
  Object.keys(w).forEach(function (h) { merged[h] = w[h]; });
  var miss = staffRegMissing_(role, merged);
  if (miss.length) return { ok: false, missing: miss, name: targetName, error: miss.join('・') + ' が未入力です（' + role + 'は 基本時給・基本バック・入店日 が必須です）' };
  if (Object.keys(w).some(function (h) { return !(cols[h] >= 0); })) return { ok: false, error: '名簿に必須項目の列がありません（先にカードの✎個別条件を1回保存してください）' };
  /* ② */
  var refs = staffMergeRefs_(pName, qName, pUid);
  if (refs.length) return { ok: false, error: '「' + pName + '」の行を他のシートが使っているため、まとめられません：' + refs.join('、') };
  /* ③ */
  var lock = LockService.getUserLock();
  if (!lock.tryLock(5000)) return { ok: false, busy: true, error: '混み合っています。少し待ってもう一度「登録を完了」を押してください（名簿は変えていません）' };
  var out;
  try { out = staffMergeLocked_(sh, targetName, role, w, cols, pUid, pName, qName); }
  catch (e) { console.error('staffMergeReg_', e); out = { ok: false, needCheck: true, error: '1行にまとめる途中で失敗しました。名簿の「' + qName + '」「' + pName + '」の行を確認してください：' + e }; }
  finally { try { lock.releaseLock(); } catch (e) {} }
  if (!out.ok) return out;
  /* 錠を返してからシフト表・完了LINE（staffRegNotifyDone_ も同じ錠を取る＝握ったまま呼ばない） */
  var synced = syncShiftSheetRole_(qName, role);
  /* 体験のとき黒服が入れたシフト行があれば、その行に LINE ID を刻む（addShiftStaff_ の既存の自己修復＝行は増えない）。
     ⚠️まとめた時だけ行う＝同じ名前の行が無い普段の完了は1回目の版と完全に同じふるまいのまま */
  try { if (staffTermsRequired_(role) && isStaffInShiftSheet_(qName)) addShiftStaff_(qName, role, '', '', pUid); } catch (e) { console.error('staffMergeReg_ シフト行', e); }
  return { ok: true, name: qName, role: role, merged: true, clearedRow: out.clearedRow, shiftSynced: synced, reg: staffRegFinish_(qName, pUid, role) };
}

/* ④〜⑦（錠の中）。戻り値 { ok, error, needCheck, clearedRow } */
function staffMergeLocked_(sh, targetName, role, w, cols, pUid, pName, qName) {
  var CHANGED = '名簿が途中で変わりました。もう一度「登録を完了」を押してください';
  var cell = function (vals, i, c) { return (i >= 1 && i < vals.length) ? String(vals[i][c] == null ? '' : vals[i][c]).trim() : null; };
  var s = function (row, c) { return String((row && row[c]) == null ? '' : row[c]).trim(); };
  /* ④ 錠の中で読み直し、2行を中身で決め直す */
  var v = sh.getDataRange().getValues();
  var width = (v[0] || []).length || sh.getLastColumn();
  var sn = staffRegSameName_(sh, v, targetName);
  if (sn.error || sn.blocked || sn.q < 0) return { ok: false, error: CHANGED + '（何も変えていません）' };
  var q = sn.q, p = sn.p;
  if (cell(v, p, 0) !== pUid || cell(v, p, 1) !== pName || cell(v, p, 2) !== '' || cell(v, q, 0) !== '' || cell(v, q, 1) !== qName) {
    return { ok: false, error: CHANGED + '（何も変えていません）' };
  }
  var readRow = function (i) { return sh.getRange(i + 1, 1, 1, width).getValues()[0]; };
  var LABEL = { A: 'LINE ID', C: '役割' };
  /* 書く予定（順番どおり）：必須3項目 → 役割 → LINE ID */
  var plan = Object.keys(w).map(function (h) { return { col: cols[h] + 1, label: h, value: w[h], orig: v[q][cols[h]] }; });
  plan.push({ col: 3, label: LABEL.C, value: role, orig: v[q][2] });
  plan.push({ col: 1, label: LABEL.A, value: pUid, orig: v[q][0] });
  var written = [];       // 書き込み命令を出した項目（反映されたかは問わない）
  var stopWhy = '';
  /* ⑤ 各書き込みの直前に、その行番号の1行だけを読んで確かめる */
  for (var k = 0; k < plan.length; k++) {
    var row;
    try { row = readRow(q); } catch (e) { stopWhy = '書く前の読み直しに失敗：' + e; break; }
    if (s(row, 1) !== qName || s(row, 0) !== '') { stopWhy = '書く前に確かめた' + (q + 1) + '行目が「' + qName + '」（LINE ID 空）ではなくなっていました'; break; }
    written.push(plan[k]);
    try { sh.getRange(q + 1, plan[k].col).setValue(plan[k].value); }
    catch (e) { stopWhy = plan[k].label + ' を書けませんでした：' + e; break; }
  }
  if (!stopWhy) {
    /* ⑥ 書いた行を1行だけ読み、書いた値そのものか */
    var after;
    try { after = readRow(q); } catch (e) { stopWhy = '書いた後の読み直しに失敗：' + e; }
    if (!stopWhy) {
      var bad = plan.filter(function (x) { return x.col === 1 || x.col === 3 ? s(after, x.col - 1) !== String(x.value) : !staffCellEq_(x.value, after[x.col - 1]); });
      if (s(after, 1) !== qName) stopWhy = '書いた後の' + (q + 1) + '行目の名前が「' + qName + '」ではありません';
      else if (bad.length) stopWhy = '書いた値が反映されていません：' + bad.map(function (x) { return x.label; }).join('・');
    }
  }
  if (stopWhy) return staffMergeUndo_(sh, q, qName, pUid, written, width, stopWhy);

  /* ⑦ #登録の行を1行だけ読み、「#登録の行そのもの」の時だけ中身を空にする（行は消さない＝位置をずらさない） */
  var prow;
  try { prow = readRow(p); } catch (e) { return staffMergeUndo_(sh, q, qName, pUid, written, width, '#登録の行の読み直しに失敗：' + e); }
  if (s(prow, 0) !== pUid || s(prow, 1) !== pName || s(prow, 2) !== '') {
    return staffMergeUndo_(sh, q, qName, pUid, written, width, '#登録の行（' + (p + 1) + '行目）が「' + pName + '」ではなくなっていました');
  }
  try { sh.getRange(p + 1, 1, 1, width).clearContent(); }
  catch (e) { return staffMergeUndo_(sh, q, qName, pUid, written, width, '#登録の行（' + (p + 1) + '行目）を空にできませんでした：' + e); }
  /* 空にした後の確かめ＝名簿全体を読み、「#登録の行」がもう無く、LINE ID がちょうど1行（既存の行）に残っているか */
  var all = null;
  try { all = sh.getDataRange().getValues(); } catch (e) { all = null; }
  var uidN = 0, pLeft = false, qStill = false, qIdx = [];
  (all || []).forEach(function (r, i) {
    if (i < 1) return;
    if (s(r, 0) === pUid) uidN++;
    if (s(r, 0) === pUid && s(r, 1) === pName && s(r, 2) === '') pLeft = true;
    /* 位置ではなく中身で見る（確かめの読みの前に人が上の行を消しても、まとまっていれば成功と言ってよい） */
    if (s(r, 0) === pUid && s(r, 1) === qName && s(r, 2) === role) { qStill = true; qIdx.push(i); }
  });
  var empty = !!all && !pLeft && uidN === 1;
  if (pLeft && qStill && uidN === 2) {
    /* 空にしたはずの#登録の行がそのまま残っている（空にする命令が反映されなかった）＝何も消していない。
       同じ LINE ID を2行に残さないよう、書いた行を戻す（戻せなければ行と項目を挙げて知らせる） */
    var still = null;
    try { still = readRow(p); } catch (e) { still = null; }
    if (still && s(still, 0) === pUid && s(still, 1) === pName && s(still, 2) === '') {
      return staffMergeUndo_(sh, q, qName, pUid, written, width, '#登録の行（' + (p + 1) + '行目）が空になりませんでした');
    }
  }
  if (pLeft && qIdx.length === 1 && uidN === 2) {
    /* #登録の行は残ったまま、別の行を空にした（空にする瞬間に人が行を削除・挿入した）。
       空にした行は戻せない（書き戻しはしない）＝行番号を挙げて変更履歴から戻すよう頼む。
       同じ LINE ID を2行に残さないよう、**自分の書いた LINE ID が入っている行**だけは戻す（位置がずれていても中身で特定できる） */
    var u = staffMergeUndo_(sh, qIdx[0], qName, pUid, written, width, '空にする瞬間に名簿の並びが変わりました');
    return { ok: false, needCheck: true,
             error: '名簿の' + (p + 1) + '行目を空にしましたが、そこは「' + pName + '」（#登録の行）ではなかった可能性があります（空にする瞬間に名簿の行が削除・挿入されました）。'
               + '名簿の' + (p + 1) + '行目の付近を確認し、消えた人の記録はスプレッドシートの変更履歴から戻してください。'
               + (u && !u.needCheck ? '「' + qName + '」の行（' + (qIdx[0] + 1) + '行目）は元の値に戻したので、確認後にもう一度「登録を完了」を押してください。' : ((u && u.error) || '')) };
  }
  if (!empty || !qStill) {
    /* 空にする瞬間に並びが変わった＝別の行を空にした可能性。書き戻しはしない（人の手作業を上書きしない）。行番号を挙げて知らせる */
    return { ok: false, needCheck: true,
             error: '1行にまとめる最後に名簿の並びが変わった可能性があります。名簿の' + (p + 1) + '行目（空にしようとした「' + pName + '」の行）と' + (q + 1) + '行目（「' + qName + '」）を確認してください：'
               + (all ? '' : '名簿を読み直せませんでした。') + (pLeft ? '#登録の「' + pName + '」の行がまだ残っています（別の行を空にした可能性）。' : '') + (all && uidN !== 1 ? 'LINE ID の行が ' + uidN + ' 行あります。' : '')
               + (all && !qStill ? '「' + qName + '」の LINE ID の行が見つかりません。' : '')
               + '空にした行に別の人の記録があった場合は、スプレッドシートの変更履歴から戻してください。' };
  }
  return { ok: true, clearedRow: p + 1 };
}

/* 書いた文字列と、シートから読み直した値が同じか（Sheets は '4000'→数値・'2026-09-14'→日付 に変える） */
function staffCellEq_(written, read) {
  var ws = String(written == null ? '' : written).trim();
  if (read instanceof Date) {
    var m = /^(\d{4})[-\/年](\d{1,2})[-\/月](\d{1,2})/.exec(ws);
    if (!m || isNaN(read.getTime())) return false;
    var y = +m[1], mo = +m[2], d = +m[3];
    var j = new Date(read.getTime() + 9 * 3600000);   // 店の暦（日本時間）でも見る＝実行環境のタイムゾーンに左右されない
    return (read.getFullYear() === y && read.getMonth() + 1 === mo && read.getDate() === d)
      || (j.getUTCFullYear() === y && j.getUTCMonth() + 1 === mo && j.getUTCDate() === d);
  }
  if (typeof read === 'number') return ws !== '' && Number(ws) === read;
  return String(read == null ? '' : read).trim() === ws;
}

/* 戻す＝**自分が書いた行だけ**（その行番号の行が、名前＝既存の行の名前・LINE ID＝自分が書いた値か空）。名前で探し直さない。
   1項目ずつ try・**LINE ID は最後**。戻した後に1行読み、元の値に戻ったかを項目ごとに確かめる。
   ⭐戻せなかった項目・確かめられなかった行があれば「元に戻しました」とは言わない＝行番号・その行の名前・項目を挙げる。 */
function staffMergeUndo_(sh, q, qName, pUid, written, width, why) {
  if (!written.length) return { ok: false, error: '名簿が途中で変わりました。もう一度「登録を完了」を押してください（何も変えていません：' + why + '）' };
  var s = function (row, c) { return String((row && row[c]) == null ? '' : row[c]).trim(); };
  var same = function (a, b) {
    if (a instanceof Date || b instanceof Date) return (a instanceof Date) && (b instanceof Date) && a.getTime() === b.getTime();
    return String(a == null ? '' : a).trim() === String(b == null ? '' : b).trim();
  };
  var labels = written.map(function (x) { return x.label; }).join('・');
  var row = null;
  try { row = sh.getRange(q + 1, 1, 1, width).getValues()[0]; } catch (e) { row = null; }
  if (!row || s(row, 1) !== qName || (s(row, 0) !== pUid && s(row, 0) !== '')) {
    var now = row ? (s(row, 1) || '名前なし') : '読めませんでした';
    return { ok: false, needCheck: true,
             error: '名簿の' + (q + 1) + '行目（いまの名前：' + now + '）を確認してください：' + labels + ' が書き換わった可能性があります。'
               + '「' + qName + '」の行も確認してください（' + why + '）。まとめる処理の途中で名簿の並びが変わったため、元に戻せませんでした。' };
  }
  written.filter(function (x) { return x.col !== 1; }).forEach(function (x) { try { sh.getRange(q + 1, x.col).setValue(x.orig); } catch (e) {} });
  var idW = written.filter(function (x) { return x.col === 1; })[0];
  if (idW && s(row, 0) === pUid) { try { sh.getRange(q + 1, 1).setValue(idW.orig); } catch (e) {} }
  var check = null;
  try { check = sh.getRange(q + 1, 1, 1, width).getValues()[0]; } catch (e) { check = null; }
  var left = check ? written.filter(function (x) { return !same(check[x.col - 1], x.orig); }) : written;
  if (left.length) {
    return { ok: false, needCheck: true,
             error: '名簿の' + (q + 1) + '行目（' + qName + '）を確認してください：' + left.map(function (x) { return x.label; }).join('・')
               + ' が書き換わったままの可能性があります（' + why + '）。' };
  }
  return { ok: false, error: '1行にまとめられませんでした。' + (q + 1) + '行目（' + qName + '）は元の値のままです（書こうとした項目：' + labels + '）。' + why };
}

/* 同じ名前で止めた時の案内（ボス決定 2026-09-14「LINEを変えて #登録し直した人も、同名で止まるまま＝改名で対応」）。
   ⭐どこで何をすれば通るかを書く＝本人が LINE で別の源氏名で #登録し直せば、在籍の人は無傷で完了できる。
   ⛔コンソールの「スタッフ改名」は、在籍の同名の人の名前と記録（シフト・勤怠・給与など）まで変えてしまう＝使わせない。 */
function staffSameNameMsg_(otherName, why) {
  var nm = String(otherName || '').trim() || '同じ名前の人';
  return '同じ名前の在籍者（' + nm + 'さん）がいるため、この名前では登録できません（源氏名を変えて登録し直す必要があります）。'
    + '本人にLINEで「#登録 別の源氏名」（例：#登録 ' + nm + '2）と送り直してもらってください。'
    + 'コンソールの「スタッフ改名」は使わないでください（在籍の' + nm + 'さんの記録まで名前が変わります）。'
    + (why ? '（止めた理由：' + why + '）' : '');
}

/* 消す行(p)の名前・LINE IDを他のシートが使っていないか。使っていれば理由の配列（空＝消してよい）。
   ⚠️名前がまとめ先(q)と**同じ文字列**なら、名前での参照はまとめた後もその行に当たる＝数えない。
   ⚠️LINE IDはまとめ先へ移る＝IDでの参照は生き続ける。**別の名前の行**に同じIDが刻まれている時だけ止める。 */
function staffMergeRefs_(pName, qName, pUid) {
  var out = [];
  var key = shiftNameKey_(qName);
  try {
    var sh = getShiftSS_().getSheetByName(SHIFT_TAB);
    if (sh && sh.getLastRow() >= 2) {
      var v = sh.getDataRange().getValues();
      var idc = v[0].map(function (x) { return String(x == null ? '' : x).trim(); }).indexOf(SHIFT_ID_HEADER);
      var nName = 0, nId = 0;
      for (var i = 1; i < v.length; i++) {
        var nm = String(v[i][0] == null ? '' : v[i][0]).trim();
        if (pName !== qName && nm === pName) nName++;
        if (idc >= 0 && String(v[i][idc] == null ? '' : v[i][idc]).trim() === pUid && shiftNameKey_(nm) !== key) nId++;
      }
      if (nName) out.push('シフト表の名前 ' + nName + '件');
      if (nId) out.push('シフト表の別の名前の行にこのLINE ID ' + nId + '件');
    }
  } catch (e) { out.push('シフト表を確かめられません'); }
  if (pName !== qName) {
    [[SHIFT_REQUEST_TAB, 1, 'シフト申請'], [KINTAI_TAB, 2, '勤怠ログ']].forEach(function (d) {
      try {
        var s2 = getOrOpenSS_().getSheetByName(d[0]);
        if (!s2 || s2.getLastRow() < 2) return;
        var n = s2.getRange(2, d[1] + 1, s2.getLastRow() - 1, 1).getValues().filter(function (r) { return String(r[0] == null ? '' : r[0]).trim() === pName; }).length;
        if (n) out.push(d[2] + ' ' + n + '件');
      } catch (e) { out.push(d[2] + 'を確かめられません'); }
    });
  }
  return out;
}

